python -c "from pathlib import Path; import re; base=Path(r'C:/Users/valtt/OneDrive/Godot/AXEL/axel_project/combat/data/symbols');
for p in base.glob('sym_*.tres'):
    text=p.read_text(encoding='utf-8')
    m=re.search(r'path=\"res://combat/art/placeholders/([^\"]+)\" id=\"2_tex\"', text)
    if not m:
        continue
    name=m.group(1)
    text=re.sub(r'\[gd_resource type=\"Resource\" load_steps=\d+ format=3\]','[gd_resource type=\"Resource\" load_steps=4 format=3]',text,count=1)
    text=re.sub(r'\[ext_resource type=\"Texture2D\" path=\"res://combat/art/placeholders/[^\"]+\" id=\"2_tex\"\]',f'[ext_resource type=\"Texture2D\" path=\"res://combat/art/grid_symbols/{name}\" id=\"2_tex\"]',text,count=1)
    if 'id="3_tex"' not in text:
        text=text.replace('[ext_resource type=\"Texture2D\" path=\"res://combat/art/grid_symbols/%s\" id=\"2_tex\"]'%name,'[ext_resource type=\"Texture2D\" path=\"res://combat/art/grid_symbols/%s\" id=\"2_tex\"]\n[ext_resource type=\"Texture2D\" path=\"res://combat/art/placeholders/%s\" id=\"3_tex\"]'%(name,name),1)
    if 'power_intro_texture = ExtResource("3_tex")' not in text:
        text=text.replace('texture = ExtResource("2_tex")','texture = ExtResource("2_tex")\npower_intro_texture = ExtResource("3_tex")',1)
    p.write_text(text,encoding='utf-8')
print('updated symbol tres files')"
